static const int g_chipDbCount = sizeof(g_chipDb) / sizeof(g_chipDb[0]);

/* ASCII case-insensitive compare (chip names are ASCII). */
static int chipNameEq(const char *a, const char *b)
{
    int i;
    if (!a || !b)
        return 0;
    for (i = 0; a[i] && b[i]; i++)
    {
        char ca = a[i], cb = b[i];
        if (ca >= 'A' && ca <= 'Z')
            ca += 'a' - 'A';
        if (cb >= 'A' && cb <= 'Z')
            cb += 'a' - 'A';
        if (ca != cb)
            return 0;
    }
    return a[i] == b[i];
}

/* Pin count for a chip name, or -1 when unknown. */
static int chipPinCount(const char *aName)
{
    int i;
    for (i = 0; i < g_chipDbCount; i++)
        if (chipNameEq(g_chipDb[i].name, aName))
            return g_chipDb[i].pins;
    return -1;
}

